package p1795037660

// approver probe (scripts/deploy-chain.sh preflight, K-4): no state, no imports.
func OK() bool { return true }

// Package types holds the value types shared by core, the minters, the
// market and the readers. Every type is plain data (no pointers into realm
// state), so passing one across a realm boundary hands over a copy and
// never a capability.
package types

import (
	"errors"
)

// State is a collection's lifecycle (design §4.1):
//
//	Draft -> Scheduled -> Minting -> Closed -> Final
//
// Scheduled->Minting and Minting->Closed happen by block height; core
// reports the effective state and materializes it on the next write.
type State int

const (
	StateDraft State = iota
	StateScheduled
	StateMinting
	StateClosed
	StateFinal
)

func (s State) String() string {
	switch s {
	case StateDraft:
		return "draft"
	case StateScheduled:
		return "scheduled"
	case StateMinting:
		return "minting"
	case StateClosed:
		return "closed"
	case StateFinal:
		return "final"
	}
	return "unknown"
}

// MaxUnitPrice caps every price (ugnot) so price*count and fee math stay
// far from int64 overflow: 1e15 ugnot = 1e9 GNOT.
const MaxUnitPrice = 1_000_000_000_000_000

// Payee receives Bps/10000 of a payment.
type Payee struct {
	Addr address
	Bps  int64
}

// CollectionSpec is what a minter asks core to create. Payees travel as
// "addr:bps,…" strings and are parsed by core, so core never stores a slice
// allocated by another realm.
type CollectionSpec struct {
	Name, Symbol, Description string
	EngineID, Params          string
	MaxSupply, RoyaltyBps     int64
	PrimaryPayees             string
	RoyaltyPayees             string
	// Soulbound makes the collection non-transferable, fixed at creation:
	// its tokens can never be transferred or approved (also not after
	// Final), the market never lists them, the owner may still burn one
	// after Final, and royaltyBps must be 0 (no secondary sales).
	Soulbound bool
}

// BeaconCommitted is the platform's commit-reveal beacon as a collection's
// randomness source (LaunchSpec.BeaconSource "" means the same).
const BeaconCommitted = "committed"

// Launch modes (LaunchSpec.Mode, CollectionInfo.Mode).
//
// ModeReveal ("") is the fair commit–reveal launch: the token map is fixed
// by the creator's secret, the beacon's (or a randomness provider's) value
// and the mint entropy, and stays hidden until Final.
//
// ModeOpen ("open") has no secrets at all: the salt is public from Launch
// (sha256("art|open|v1|" + chainId + "|" + cid)), so anyone can compute
// every token's art before minting. For badges, editions, event drops and
// 1/1s. An open collection has no commitment, no beacon or provider, no
// creator reserve, is never a fair launch (badge "open"), and its tokens
// still stay locked until Final, which anyone may call once the sale ended
// or sold out.
const (
	ModeReveal = ""
	ModeOpen   = "open"
)

// LaunchSpec freezes a collection's sale window and commitments (I-6).
//
// BeaconSource picks the second entropy source when UseBeacon is set:
// "" or BeaconCommitted for the platform beacon's commit-reveal, or the
// package path of an admin-approved randomness provider realm (e.g. a drand
// relay); it must be "" without UseBeacon.
//
// Mode is ModeReveal ("") or ModeOpen. An open launch needs RevealWindow 0,
// CreatorCommit "", UseBeacon false and BeaconSource "".
type LaunchSpec struct {
	StartHeight, EndHeight int64
	RevealWindow           int64 // blocks after close; core bounds it (0 in open mode)
	CreatorCommit          string
	UseBeacon              bool
	BeaconSource           string
	Mode                   string
}

// CollectionInfo is core's typed read model for other realms.
type CollectionInfo struct {
	ID, Name, Symbol, Description string
	Creator                       address
	Minter, EngineID, Params      string
	State                         State
	MaxSupply, Minted, Reserved   int64
	StartHeight, EndHeight        int64
	RevealDeadline                int64 // 0 before Launch
	RoyaltyBps                    int64
	Badge                         string   // provenance badge once Final
	Mode                          string   // ModeReveal ("") or ModeOpen; "" before Launch
	TraitTypes                    []string // the collection's trait types (a copy)
	Salt                          string   // final salt (hex); "" before Final
	Soulbound                     bool     // non-transferable (CollectionSpec.Soulbound)
}

// Fees are the protocol's fee parameters; core enforces hard caps.
type Fees struct {
	CreateFee    int64 // ugnot per collection
	PrimaryBps   int64 // of every primary sale
	SecondaryBps int64 // of every market sale
	Treasury     address
	EngineCapBps int64 // platform cap on engine-author fees (<= engine.MaxFeeBps)
}

// Phase kinds.
const (
	PhaseAllow  = "allow"
	PhasePublic = "public"
)

// Phase is one sale window. A fixed price has StartPrice == FloorPrice and
// no steps; a Dutch auction starts at StartPrice and drops StepAmount every
// StepBlocks until FloorPrice (design §4.5). WalletCap counts lifetime
// mints of the collection (I-9); 0 means no cap.
type Phase struct {
	Kind, Set              string
	StartHeight, EndHeight int64
	StartPrice, FloorPrice int64
	StepBlocks, StepAmount int64
	WalletCap              int64
}

// Validate checks a phase in isolation; the minter checks the set grammar
// and how phases relate to each other.
func (p Phase) Validate() error {
	switch p.Kind {
	case PhasePublic:
		if p.Set != "" {
			return errors.New("a public phase has no allowlist set")
		}
	case PhaseAllow:
		if p.Set == "" {
			return errors.New("an allow phase needs a set")
		}
	default:
		return errors.New("phase kind must be allow or public")
	}
	if p.StartHeight <= 0 || p.EndHeight < p.StartHeight {
		return errors.New("phase heights must satisfy 0 < start <= end")
	}
	if p.FloorPrice < 0 || p.StartPrice < p.FloorPrice || p.StartPrice > MaxUnitPrice {
		return errors.New("prices must satisfy 0 <= floor <= start <= MaxUnitPrice")
	}
	if p.StartPrice == p.FloorPrice {
		if p.StepBlocks != 0 || p.StepAmount != 0 {
			return errors.New("a fixed-price phase has no steps")
		}
	} else if p.StepBlocks <= 0 || p.StepAmount <= 0 {
		return errors.New("a Dutch phase needs positive stepBlocks and stepAmount")
	}
	if p.WalletCap < 0 {
		return errors.New("walletCap must be >= 0")
	}
	return nil
}

// Covers reports whether height h is inside the phase window.
func (p Phase) Covers(h int64) bool {
	return h >= p.StartHeight && h <= p.EndHeight
}

// PriceAt is the unit price at height h:
//
//	max(floor, start - floor((h-startH)/stepBlocks) * stepAmount)
//
// computed so that no intermediate value can overflow.
func (p Phase) PriceAt(h int64) int64 {
	if p.StartPrice == p.FloorPrice || h <= p.StartHeight {
		return p.StartPrice
	}
	steps := (h - p.StartHeight) / p.StepBlocks
	if steps > (p.StartPrice-p.FloorPrice)/p.StepAmount {
		return p.FloorPrice
	}
	price := p.StartPrice - steps*p.StepAmount
	if price < p.FloorPrice {
		return p.FloorPrice
	}
	return price
}

package safe

// AvgBlockMs is the measured mainnet average block time (RA §1: 200k blocks
// in 708,660 s). Use it only for UI estimates and defaults; every on-chain
// rule is stated in blocks.
const AvgBlockMs = 3540

// BlocksFor converts a duration to blocks, rounding up.
func BlocksFor(seconds int64) int64 {
	if seconds <= 0 {
		return 0
	}
	return (seconds*1000 + AvgBlockMs - 1) / AvgBlockMs
}

package safe

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

// MaxMerkleDepth bounds a proof: 2^32 leaves is far beyond any allowlist.
const MaxMerkleDepth = 32

func Sha256Hex(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

// --- commit–reveal v2 (design §4.2) --------------------------------------
//
// Every formula is domain-separated by platform, purpose, version, chain and
// collection, so a secret or commit is useless anywhere else (RA M-5). They
// live here, not in core, so the frontend's verifier, the beacon service and
// the tests all port one definition.

// Commit is the value a creator ("creator") or the beacon ("beacon") commits
// to for collection cid on chain chainID.
func Commit(chainID, cid, role, secret string) string {
	return Sha256Hex(Domain + "|commit|v2|" + chainID + "|" + cid + "|" + role + "|" + secret)
}

// InitialEntropy seeds a collection's mint-entropy accumulator.
func InitialEntropy(chainID, cid string) string {
	return Sha256Hex(Domain + "|acc|v2|" + chainID + "|" + cid)
}

// MixEntropy folds one mint call into the accumulator. The inputs are
// public, but none existed when the secrets were committed, which is what
// stops a committer from choosing the map their own mints receive.
func MixEntropy(acc string, to address, height, first, last int64) string {
	return Sha256Hex(acc + "|" + to.String() + "|" + strconv.FormatInt(height, 10) + "|" +
		strconv.FormatInt(first, 10) + "-" + strconv.FormatInt(last, 10))
}

// Salt binds both secrets ("" when not revealed) to the final accumulator.
func Salt(cid, creatorSecret, beaconSecret, acc string) string {
	return Sha256Hex(Domain + "|salt|v2|" + cid + "|" + creatorSecret + "|" + beaconSecret + "|" + acc)
}

// Seed is the per-token engine seed once the salt is final.
func Seed(cid, tid, salt string) string {
	return Sha256Hex(Domain + "|seed|v1|" + cid + "|" + tid + "|" + salt)
}

// --- allowlist merkle proofs (design §4.6) -------------------------------

// AllowlistLeaf is the leaf for addr in collection cid's allowlist tree.
func AllowlistLeaf(cid string, addr address) string {
	return Sha256Hex(Domain + "|al|v1|" + cid + "|" + addr.String())
}

// MerkleVerify checks a sorted-pair sha256 proof ("hex,hex,…", leaf to
// root). An empty proof means the tree has a single leaf equal to the root.
// Malformed input is simply false: proofs come from untrusted callers.
func MerkleVerify(rootHex, leafHex, proof string) bool {
	root, err := hex.DecodeString(rootHex)
	if err != nil || len(root) != 32 {
		return false
	}
	node, err := hex.DecodeString(leafHex)
	if err != nil || len(node) != 32 {
		return false
	}
	if proof != "" {
		steps := strings.Split(proof, ",")
		if len(steps) > MaxMerkleDepth {
			return false
		}
		for _, step := range steps {
			sibling, err := hex.DecodeString(step)
			if err != nil || len(sibling) != 32 {
				return false
			}
			node = hashPair(node, sibling)
		}
	}
	return bytes.Equal(node, root)
}

// MerkleNodeTag prefixes every inner node (SA-I2): an inner node hashes
// 0x01 || lo || hi, while a leaf is the hash of a text that starts with
// Domain ("art|al|v1|…"), so an inner node can never be presented as a leaf
// or the other way round.
const MerkleNodeTag = byte(0x01)

// hashPair hashes the two children in byte order, so a proof needs no
// left/right flags.
func hashPair(a, b []byte) []byte {
	if bytes.Compare(b, a) < 0 {
		a, b = b, a
	}
	buf := make([]byte, 0, 65)
	buf = append(buf, MerkleNodeTag)
	buf = append(buf, a...)
	buf = append(buf, b...)
	sum := sha256.Sum256(buf)
	return sum[:]
}

// MerkleParent is hashPair on hex nodes, for tests and the off-chain builder.
func MerkleParent(aHex, bHex string) string {
	a, errA := hex.DecodeString(aHex)
	b, errB := hex.DecodeString(bHex)
	if errA != nil || errB != nil {
		panic("MerkleParent: invalid hex")
	}
	return hex.EncodeToString(hashPair(a, b))
}

package safe

import (
	"chain/markdown"
	"strconv"
	"strings"
)

// Byte classes as 128-bit bitmaps for the native markdown.MatchCharsetN
// (one call checks a whole string at ~0.7 gas per byte; bytes >= 0x80 never
// match). jsonSafe: printable ASCII that JSONString copies unchanged (not
// '"', '\', '<', '>', '&', DEL). rawSafe: [A-Za-z0-9+/=:;,._-].
const (
	jsonSafeLo = 0xafffffbb00000000
	jsonSafeHi = 0x7fffffffefffffff
	rawSafeLo  = 0x2ffff80000000000
	rawSafeHi  = 0x07fffffe87fffffe
	// jsonFastMin: below this length the byte loop is cheaper than the
	// native call.
	jsonFastMin = 8
)

// JSONString returns s as a quoted JSON string. Beyond the mandatory
// escapes it also escapes U+2028/U+2029 (RA L-12) and '<', '>', '&', so the
// output is safe to inline in HTML as well. Strings that need no escape
// (printable ASCII without '"', '\', '<', '>', '&') take a native fast
// path; the output is the same.
func JSONString(s string) string {
	if len(s) >= jsonFastMin && markdown.MatchCharsetN(s, jsonSafeLo, jsonSafeHi, jsonSafeLo, jsonSafeHi, 0, len(s)) {
		return "\"" + s + "\""
	}
	const hexDigits = "0123456789abcdef"
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '<', '>', '&', 0x2028, 0x2029:
			b.WriteString(`\u`)
			b.WriteString(PadHex(int64(r), 4))
		default:
			if r < 0x20 || r == 0x7f {
				b.WriteString(`\u00`)
				b.WriteByte(hexDigits[(r>>4)&0xf])
				b.WriteByte(hexDigits[r&0xf])
				continue
			}
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// PadHex renders n in lowercase hex, zero-padded to width.
func PadHex(n int64, width int) string {
	s := strconv.FormatInt(n, 16)
	if len(s) >= width {
		return s
	}
	return strings.Repeat("0", width-len(s)) + s
}

// JSONWriter is the single JSON producer of every read API (design
// §2.5: reads return primitives or JSON, never positional text). It tracks
// commas itself, so callers only describe structure:
//
//	w := &safe.JSONWriter{}
//	w.BeginObject(); w.Key("id"); w.Str("1"); w.EndObject()
type JSONWriter struct {
	b        strings.Builder
	hasItems []bool // one entry per open container
	afterKey bool
}

func (w *JSONWriter) BeginObject() { w.open('{') }
func (w *JSONWriter) EndObject()   { w.close('}') }
func (w *JSONWriter) BeginArray()  { w.open('[') }
func (w *JSONWriter) EndArray()    { w.close(']') }

// Key starts an object member; the next value call writes its value.
func (w *JSONWriter) Key(k string) {
	w.separate()
	w.b.WriteString(JSONString(k))
	w.b.WriteByte(':')
	w.afterKey = true
}

func (w *JSONWriter) Str(v string) { w.value(JSONString(v)) }
func (w *JSONWriter) Int(v int64)  { w.value(strconv.FormatInt(v, 10)) }
func (w *JSONWriter) Bool(v bool)  { w.value(strconv.FormatBool(v)) }

// Raw writes v verbatim. Only for JSON produced by another JSONWriter.
func (w *JSONWriter) Raw(v string) { w.value(v) }

// RawStr writes v as a JSON string without escaping. v may only hold
// [A-Za-z0-9+/=:;,._-] (base64, hex, decimal, a data: URI header), which
// JSON never escapes; any other byte panics. One native pass instead of a
// rune loop: a 350 KB data URI costs well under 1M gas (M-4, UP-I1).
func (w *JSONWriter) RawStr(v string) {
	if !markdown.MatchCharsetN(v, rawSafeLo, rawSafeHi, rawSafeLo, rawSafeHi, 0, len(v)) {
		panic("JSONWriter: RawStr value may only hold [A-Za-z0-9+/=:;,._-]")
	}
	w.separate()
	w.b.WriteByte('"')
	w.b.WriteString(v)
	w.b.WriteByte('"')
}

// RawStrField is Key + RawStr.
func (w *JSONWriter) RawStrField(k, v string) { w.Key(k); w.RawStr(v) }

// StrField and IntField are Key+value shorthands.
func (w *JSONWriter) StrField(k, v string) { w.Key(k); w.Str(v) }
func (w *JSONWriter) IntField(k string, v int64) { w.Key(k); w.Int(v) }
func (w *JSONWriter) BoolField(k string, v bool) { w.Key(k); w.Bool(v) }

func (w *JSONWriter) String() string { return w.b.String() }

func (w *JSONWriter) open(c byte) {
	w.separate()
	w.b.WriteByte(c)
	w.hasItems = append(w.hasItems, false)
}

func (w *JSONWriter) close(c byte) {
	if len(w.hasItems) == 0 {
		panic("JSONWriter: close without open")
	}
	w.hasItems = w.hasItems[:len(w.hasItems)-1]
	w.b.WriteByte(c)
}

func (w *JSONWriter) value(v string) {
	w.separate()
	w.b.WriteString(v)
}

// separate writes the comma before an item, except right after a key.
func (w *JSONWriter) separate() {
	if w.afterKey {
		w.afterKey = false
		return
	}
	if n := len(w.hasItems); n > 0 {
		if w.hasItems[n-1] {
			w.b.WriteByte(',')
		}
		w.hasItems[n-1] = true
	}
}

package safe

import (
	"encoding/hex"
	"errors"
	"strconv"
)

// Media checks, moved in from p/media/v1 (image.gno, cid.gno) so core can
// validate an engine's media (mainnet plan §2.1, M-3) without importing an
// upload package. Behaviour and error texts are unchanged ("media: …");
// the frontend twins are chain/cid.ts and the image header check of the
// upload layer (docs/test-vectors/upload-v1.json).

// IANA media types CheckImage and ImageDims understand. GIF is parsed for
// completeness; callers decide which types they accept.
const (
	MimeSVG  = "image/svg+xml"
	MimePNG  = "image/png"
	MimeWebP = "image/webp"
	MimeJPEG = "image/jpeg"
	MimeGIF  = "image/gif"
)

// Media limits.
const (
	MaxDim           = 4096  // px per side, decompression-bomb guard
	MaxSVGImageBytes = 16384 // CheckImage's AssertSVG cap for an SVG file
)

// CID codecs.
const (
	CodecRaw   = 0x55
	CodecDagPB = 0x70
)

// IPFSScheme prefixes an IPFS URI.
const IPFSScheme = "ipfs://"

func mediaErr(msg string) error { return errors.New("media: " + msg) }

// mimeShort is the short name used in error texts ("png", …), "" when the
// type is not a raster type ImageDims parses.
func mimeShort(mime string) string {
	switch mime {
	case MimePNG:
		return "png"
	case MimeWebP:
		return "webp"
	case MimeJPEG:
		return "jpeg"
	case MimeGIF:
		return "gif"
	}
	return ""
}

// CheckImage checks a complete file against its declared IANA type: an SVG
// must pass AssertSVG with MaxSVGImageBytes; a raster file must carry the
// type's magic bytes and header dimensions of 1..MaxDim per side
// (ImageDims). Nothing else of a raster file is parsed: raster bytes are
// only ever shown through <img> (SA-M3).
func CheckImage(mime, data string) error {
	if mime == MimeSVG {
		return AssertSVG(data, MaxSVGImageBytes)
	}
	_, _, err := ImageDims(mime, data)
	return err
}

// ImageDims returns a raster file's pixel dimensions after checking its
// magic bytes and header (PNG IHDR, WebP VP8/VP8L/VP8X, JPEG SOFn, GIF
// logical screen) and the 1..MaxDim bound per side.
func ImageDims(mime, data string) (w, h int, err error) {
	switch mime {
	case MimePNG:
		w, h, err = pngDims(data)
	case MimeWebP:
		w, h, err = webpDims(data)
	case MimeJPEG:
		w, h, err = jpegDims(data)
	case MimeGIF:
		w, h, err = gifDims(data)
	default:
		return 0, 0, mediaErr("unknown media type " + strconv.Quote(mime))
	}
	if err != nil {
		return 0, 0, err
	}
	if w < 1 || h < 1 || w > MaxDim || h > MaxDim {
		return 0, 0, mediaErr(mimeShort(mime) + ": dimensions " + strconv.Itoa(w) + "x" + strconv.Itoa(h) +
			" outside 1.." + strconv.Itoa(MaxDim))
	}
	return w, h, nil
}

func be16(s string, i int) int { return int(s[i])<<8 | int(s[i+1]) }
func le16(s string, i int) int { return int(s[i]) | int(s[i+1])<<8 }
func le24(s string, i int) int { return int(s[i]) | int(s[i+1])<<8 | int(s[i+2])<<16 }
func be32(s string, i int) int64 {
	return int64(s[i])<<24 | int64(s[i+1])<<16 | int64(s[i+2])<<8 | int64(s[i+3])
}
func le32(s string, i int) int64 {
	return int64(s[i]) | int64(s[i+1])<<8 | int64(s[i+2])<<16 | int64(s[i+3])<<24
}

// pngDims: signature, then the IHDR chunk (length 13) with big-endian
// width and height. The 4-byte CRC after IHDR must be present.
func pngDims(s string) (int, int, error) {
	if len(s) < 33 || s[:8] != "\x89PNG\r\n\x1a\n" {
		return 0, 0, mediaErr("png: bad signature or truncated header")
	}
	if be32(s, 8) != 13 || s[12:16] != "IHDR" {
		return 0, 0, mediaErr("png: first chunk must be IHDR")
	}
	return int(be32(s, 16)), int(be32(s, 20)), nil
}

// webpDims: RIFF container whose size field covers the whole file, form
// type WEBP, then one of the three bitstream headers.
func webpDims(s string) (int, int, error) {
	if len(s) < 30 || s[:4] != "RIFF" || s[8:12] != "WEBP" {
		return 0, 0, mediaErr("webp: bad RIFF/WEBP header or truncated")
	}
	if le32(s, 4)+8 != int64(len(s)) {
		return 0, 0, mediaErr("webp: RIFF size does not match the file size")
	}
	switch s[12:16] {
	case "VP8 ": // lossy: 3-byte frame tag, start code 9d 01 2a, 14-bit dims
		if s[23:26] != "\x9d\x01\x2a" {
			return 0, 0, mediaErr("webp: bad VP8 start code")
		}
		return le16(s, 26) & 0x3fff, le16(s, 28) & 0x3fff, nil
	case "VP8L": // lossless: signature 0x2f, 14-bit width-1 and height-1
		if s[20] != 0x2f {
			return 0, 0, mediaErr("webp: bad VP8L signature")
		}
		bits := le32(s, 21)
		return int(bits&0x3fff) + 1, int((bits>>14)&0x3fff) + 1, nil
	case "VP8X": // extended: 24-bit canvas width-1 and height-1
		return le24(s, 24) + 1, le24(s, 27) + 1, nil
	}
	return 0, 0, mediaErr("webp: unknown bitstream chunk")
}

// jpegDims walks the marker segments after SOI up to the first SOFn
// (C0..CF except C4 DHT, C8 JPG, CC DAC). Reaching SOS or EOI first, or
// running out of bytes, is an error.
func jpegDims(s string) (int, int, error) {
	if len(s) < 4 || s[0] != 0xff || s[1] != 0xd8 || s[2] != 0xff {
		return 0, 0, mediaErr("jpeg: bad SOI")
	}
	i := 2
	for i < len(s) {
		if s[i] != 0xff {
			return 0, 0, mediaErr("jpeg: expected a marker at byte " + strconv.Itoa(i))
		}
		for i < len(s) && s[i] == 0xff { // fill bytes
			i++
		}
		if i >= len(s) {
			break
		}
		m := s[i]
		i++
		switch {
		case m == 0xd8 || m == 0x01 || (m >= 0xd0 && m <= 0xd7):
			continue // standalone markers
		case m == 0xd9 || m == 0xda:
			return 0, 0, mediaErr("jpeg: no frame header before scan data")
		}
		if i+2 > len(s) {
			break
		}
		n := be16(s, i)
		if n < 2 || i+n > len(s) {
			return 0, 0, mediaErr("jpeg: bad segment length")
		}
		if m >= 0xc0 && m <= 0xcf && m != 0xc4 && m != 0xc8 && m != 0xcc {
			if n < 8 {
				return 0, 0, mediaErr("jpeg: short frame header")
			}
			return be16(s, i+5), be16(s, i+3), nil // width after height
		}
		i += n
	}
	return 0, 0, mediaErr("jpeg: truncated before the frame header")
}

func gifDims(s string) (int, int, error) {
	if len(s) < 13 || (s[:6] != "GIF87a" && s[:6] != "GIF89a") {
		return 0, 0, mediaErr("gif: bad signature or truncated")
	}
	return le16(s, 6), le16(s, 8), nil
}

// CIDv1 grammar (design §12.1; frontend chain/cid.ts is the twin):
// multibase 'b' (RFC 4648 base32, lower case, no padding) over exactly
// 0x01 · codec · 0x12 · 0x20 · digest[32], codec 0x55 (raw) or 0x70
// (dag-pb). That is 36 bytes = 58 base32 characters + 'b'. The unused two
// trailing bits must be zero, so every CID has exactly one spelling. CIDv0
// ("Qm…"), upper case, other bases, codecs or hash functions are refused.

const (
	b32Alphabet = "abcdefghijklmnopqrstuvwxyz234567"
	cidBytes    = 36
	cidChars    = 58 // ceil(36*8/5)
	mhSha256    = 0x12
	digestLen   = 32
)

// ParseCIDv1 returns the codec (CodecRaw or CodecDagPB) and the sha2-256
// digest as lower-case hex.
func ParseCIDv1(s string) (codec int, digestHex string, err error) {
	if s == "" {
		return 0, "", mediaErr("cid: empty")
	}
	if len(s) >= 2 && s[0] == 'Q' && s[1] == 'm' {
		return 0, "", mediaErr("cid: CIDv0 is not accepted; convert it to CIDv1")
	}
	if s[0] != 'b' {
		return 0, "", mediaErr("cid: multibase must be 'b' (base32 lower case)")
	}
	if len(s) != cidChars+1 {
		return 0, "", mediaErr("cid: expected " + strconv.Itoa(cidChars+1) + " characters, got " + strconv.Itoa(len(s)))
	}
	bz, derr := base32Decode(s[1:])
	if derr != nil {
		return 0, "", derr
	}
	if len(bz) != cidBytes {
		return 0, "", mediaErr("cid: wrong length")
	}
	if bz[0] != 1 {
		return 0, "", mediaErr("cid: version must be 1")
	}
	c := int(bz[1])
	if c != CodecRaw && c != CodecDagPB {
		return 0, "", mediaErr("cid: codec must be raw (0x55) or dag-pb (0x70)")
	}
	if bz[2] != mhSha256 || bz[3] != digestLen {
		return 0, "", mediaErr("cid: multihash must be sha2-256")
	}
	return c, hex.EncodeToString(bz[4:]), nil
}

// IsIPFSURI reports whether s is IPFSScheme followed by a CIDv1 that
// ParseCIDv1 accepts.
func IsIPFSURI(s string) bool {
	if len(s) <= len(IPFSScheme) || s[:len(IPFSScheme)] != IPFSScheme {
		return false
	}
	_, _, err := ParseCIDv1(s[len(IPFSScheme):])
	return err == nil
}

// CIDFromDigest is the inverse of ParseCIDv1. It panics on an unsupported
// codec or a digest that is not 64 lower-case hex characters.
func CIDFromDigest(codec int, digestHex string) string {
	if codec != CodecRaw && codec != CodecDagPB {
		panic("media: cid: unsupported codec")
	}
	d, ok := Raw32(digestHex)
	if !ok {
		panic("media: cid: digest must be 64 lower-case hex characters")
	}
	bz := make([]byte, 0, cidBytes)
	bz = append(bz, 1, byte(codec), mhSha256, digestLen)
	bz = append(bz, d...)
	return "b" + base32Encode(bz)
}

// IsHex32 reports whether s is exactly 64 lower-case hex characters.
func IsHex32(s string) bool {
	_, ok := Raw32(s)
	return ok
}

// Raw32 decodes exactly 64 lower-case hex characters into 32 raw bytes
// (one pass, table lookups).
func Raw32(s string) (string, bool) {
	if len(s) != 64 {
		return "", false
	}
	out := make([]byte, 32)
	for i := 0; i < 32; i++ {
		hi, lo := hexRev[s[2*i]], hexRev[s[2*i+1]]
		if hi > 15 || lo > 15 {
			return "", false
		}
		out[i] = hi<<4 | lo
	}
	return string(out), true
}

// hexRev and b32Rev map a byte to its digit value, 0xff when it is not a
// lower-case hex / base32 digit.
const (
	hexRev = "\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x0a\x0b\x0c\x0d\x0e\x0f\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff"
	b32Rev = "\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x1a\x1b\x1c\x1d\x1e\x1f\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c\x0d\x0e\x0f\x10\x11\x12\x13\x14\x15\x16\x17\x18\x19\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff"
)

func base32Encode(bz []byte) string {
	out := make([]byte, 0, (len(bz)*8+4)/5)
	var buf uint32
	bits := uint(0)
	for _, b := range bz {
		buf = buf<<8 | uint32(b)
		bits += 8
		for bits >= 5 {
			bits -= 5
			out = append(out, b32Alphabet[(buf>>bits)&31])
		}
		buf &= (1 << bits) - 1
	}
	if bits > 0 {
		out = append(out, b32Alphabet[(buf<<(5-bits))&31])
	}
	return string(out)
}

// base32Decode is strict: lower-case alphabet only, and the unused
// trailing bits must be zero.
func base32Decode(s string) ([]byte, error) {
	out := make([]byte, 0, len(s)*5/8)
	var buf uint32
	bits := uint(0)
	for i := 0; i < len(s); i++ {
		v := b32Rev[s[i]]
		if v > 31 {
			return nil, mediaErr("cid: invalid base32 character " + strconv.Quote(s[i:i+1]))
		}
		buf = buf<<5 | uint32(v)
		bits += 5
		if bits >= 8 {
			bits -= 8
			out = append(out, byte(buf>>bits))
			buf &= (1 << bits) - 1
		}
	}
	if bits >= 5 || buf != 0 {
		return nil, mediaErr("cid: non-canonical base32 padding bits")
	}
	return out, nil
}

package safe

import (
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/types/v2"
)

// BpsDenominator is 100% in basis points (EIP-2981, royalty/v0).
const BpsDenominator = 10000

// BpsOf returns floor(amount * bps / 10000) without ever forming the full
// product, so it cannot overflow for any amount >= 0 and 0 <= bps <= 10000.
func BpsOf(amount, bps int64) int64 {
	if amount < 0 {
		panic("BpsOf: negative amount")
	}
	if bps < 0 || bps > BpsDenominator {
		panic("BpsOf: bps out of range")
	}
	return (amount/BpsDenominator)*bps + (amount%BpsDenominator)*bps/BpsDenominator
}

// AssertBps panics unless 0 <= bps <= cap.
func AssertBps(field string, bps, cap int64) {
	if bps < 0 || bps > cap {
		panic(field + ": must be between 0 and " + strconv.FormatInt(cap, 10) + " bps")
	}
}

// ParsePayees parses "g1…:7000,g1…:3000": 1..max distinct valid addresses,
// each with a positive share, shares summing to exactly 10000.
func ParsePayees(field, s string, max int) []types.Payee {
	if s == "" {
		panic(field + ": must not be empty")
	}
	parts := strings.Split(s, ",")
	if len(parts) > max {
		panic(field + ": at most " + strconv.Itoa(max) + " payees")
	}
	out := make([]types.Payee, 0, len(parts))
	var total int64
	for _, part := range parts {
		addrStr, bpsStr, ok := strings.Cut(part, ":")
		if !ok {
			panic(field + ": expected address:bps, got " + strconv.Quote(part))
		}
		addr := address(addrStr)
		if !addr.IsValid() {
			panic(field + ": invalid address " + strconv.Quote(addrStr))
		}
		bps, err := strconv.ParseInt(bpsStr, 10, 64)
		if err != nil || bps <= 0 || bps > BpsDenominator {
			panic(field + ": invalid share " + strconv.Quote(bpsStr))
		}
		for _, p := range out {
			if p.Addr == addr {
				panic(field + ": duplicate payee " + addrStr)
			}
		}
		total += bps
		out = append(out, types.Payee{Addr: addr, Bps: bps})
	}
	if total != BpsDenominator {
		panic(field + ": shares must sum to 10000 bps, got " + strconv.FormatInt(total, 10))
	}
	return out
}

// FormatPayees is the inverse of ParsePayees.
func FormatPayees(ps []types.Payee) string {
	parts := make([]string, len(ps))
	for i, p := range ps {
		parts[i] = p.Addr.String() + ":" + strconv.FormatInt(p.Bps, 10)
	}
	return strings.Join(parts, ",")
}

// SplitByBps divides amount by the payees' shares. The rounding remainder
// goes to the first payee, so the parts always sum to exactly amount — the
// property every "no balance left behind" invariant (I-3, I-4) relies on.
func SplitByBps(amount int64, ps []types.Payee) []int64 {
	if len(ps) == 0 {
		panic("SplitByBps: no payees")
	}
	out := make([]int64, len(ps))
	var given int64
	for i, p := range ps {
		out[i] = BpsOf(amount, p.Bps)
		given += out[i]
	}
	out[0] += amount - given
	return out
}

